// Decision sketch — say this out loud, then pick
type Pick = 'next' | 'vite-spa'
export function pickFramework(p: {
  seo: boolean
  existingBff: boolean
  closedLogin: boolean
  teamWantsRsc: boolean
}): Pick {
  if (p.seo) return 'next'
  if (p.closedLogin && p.existingBff && !p.teamWantsRsc) return 'vite-spa'
  if (!p.teamWantsRsc && p.existingBff) return 'vite-spa'
  return 'next'
}
// Logged-in admin, mature API → vite-spa. Docs + app, cookies → next.

