// Pitfall: server HTML "en-US 10/08" vs client "vi-VN 08/10"
export function CreatedAt({ iso }: { iso: string }) {
  // ❌ locale and timezone follow the machine, not the request
  // return <time>{new Date(iso).toLocaleDateString()}</time>
  // ✅ serialize on the server with an explicit locale
  const text = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'UTC', dateStyle: 'medium',
  }).format(new Date(iso))
  return <time dateTime={iso}>{text}</time>
}
